<script setup lang="ts">import {computed,ref} from 'vue';import ToolPageHeader from '@/components/tool/ToolPageHeader.vue';import ToolDocumentation from '@/components/tool/ToolDocumentation.vue';import {countCharacters} from '../lib/countCharacters';const input=ref('');const stats=computed(()=>countCharacters(input.value));const metrics=computed(()=>[['汉字',stats.value.han],['中文符号',stats.value.chinesePunctuation],['字母',stats.value.letters],['英文符号',stats.value.englishPunctuation],['数字',stats.value.digits],['空格',stats.value.spaces],['换行',stats.value.newlines],['制表符',stats.value.tabs],['其他字符',stats.value.other]] as const);const docs=[{title:'加权计算规则',content:'总字符数 = 汉字×2 + 中文符号×2 + 字母 + 英文符号 + 数字 + 空格 + 换行 + 制表符 + 其他字符。'},{title:'原始字符数',content:'原始字符数按用户感知的 Unicode 字符遍历，常见 Emoji 不会因为代理对而被重复计算。'},{title:'分类边界',content:'汉字使用 Unicode Han Script 判断；未归入既定类别的 Emoji 和其他语言字符统一计入其他字符。'}]</script>
<template><div class="sr-page"><ToolPageHeader category="文本处理" title="字符数统计" description="实时分类统计文本，并按约定规则计算加权字符数。" :tags="['字符','统计']"/><section class="counter"><div class="input sr-panel"><label>待统计文本</label><textarea v-model="input" placeholder="在这里输入或粘贴文本…"></textarea><el-button class="sr-secondary-button" @click="input=''">清空文本</el-button></div><div class="result sr-panel"><div class="totals"><div><span>加权总字符数</span><strong>{{stats.weighted}}</strong></div><div><span>原始字符数</span><strong>{{stats.raw}}</strong></div></div><div class="metrics"><div v-for="[name,value] in metrics" :key="name"><span>{{name}}</span><b>{{value}}</b></div></div></div></section><div class="formula">总字符数 = 汉字×2 + 中文符号×2 + 字母 + 英文符号 + 数字 + 空格 + 换行 + 制表符 + 其他字符</div><ToolDocumentation :sections="docs"/></div></template>
<style scoped lang="scss">.counter{display:grid;grid-template-columns:1.35fr 1fr;gap:14px}.input,.result{padding:20px}.input label{font-size:14px;font-weight:600}.input textarea{width:100%;height:320px;margin-top:10px;padding:14px;border:1px solid var(--sr-border);border-radius:var(--sr-radius-control);resize:vertical;background:var(--sr-surface-soft);color:var(--sr-text);font-size:14px;line-height:1.65}.input textarea:focus{outline:0;border-color:var(--sr-blue)}.input .el-button{margin-top:10px}.totals{display:grid;grid-template-columns:1fr 1fr;gap:10px}.totals div{padding:15px;border-radius:var(--sr-radius-control);background:var(--sr-blue-soft)}.totals span,.metrics span{display:block;color:var(--sr-text-muted);font-size:12px}.totals strong{display:block;margin-top:5px;color:var(--sr-blue);font-size:27px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-top:14px;background:var(--sr-border)}.metrics div{padding:13px;background:var(--sr-surface)}.metrics b{display:block;margin-top:5px;font-size:17px}.formula{margin-top:14px;padding:14px;border-left:3px solid var(--sr-orange);background:var(--sr-orange-soft);font-size:13px;line-height:1.6}@media(max-width:800px){.counter{grid-template-columns:1fr}}</style>
